from __future__ import annotations

import argparse
import base64
import hashlib
import json
import os
import queue
import shutil
import socket
import subprocess
import tempfile
import threading
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer


events: list[tuple[float, str, str, str]] = []
http_success = True
ws_connect_fail = False


class MockResponses(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def do_GET(self):
        events.append((time.monotonic(), "WS", self.path, self.headers.get("Upgrade", "")))
        if ws_connect_fail:
            self.send_response(503)
            self.send_header("Content-Length", "0")
            self.end_headers()
            return
        key = self.headers.get("Sec-WebSocket-Key")
        if not key:
            self.send_response(400)
            self.send_header("Content-Length", "0")
            self.end_headers()
            return
        accept = base64.b64encode(
            hashlib.sha1((key + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11").encode()).digest()
        ).decode()
        self.send_response(101)
        self.send_header("Upgrade", "websocket")
        self.send_header("Connection", "Upgrade")
        self.send_header("Sec-WebSocket-Accept", accept)
        self.end_headers()
        self.wfile.flush()
        time.sleep(0.15)
        try:
            self.connection.shutdown(socket.SHUT_RDWR)
        except OSError:
            pass
        self.connection.close()

    def do_POST(self):
        events.append((time.monotonic(), "HTTP", self.path, ""))
        length = int(self.headers.get("Content-Length", "0"))
        if length:
            self.rfile.read(length)
        if not http_success:
            self.send_response(503)
            self.send_header("Content-Length", "0")
            self.end_headers()
            return
        item = {"type": "response.output_item.done", "item": {"type": "message", "role": "assistant", "content": [{"type": "output_text", "text": "Local test summary."}]}}
        completed = {"type": "response.completed", "response": {"id": "local-compact-response"}}
        body = "".join(f"event: {event['type']}\ndata: {json.dumps(event)}\n\n" for event in (item, completed)).encode()
        self.send_response(200)
        self.send_header("Content-Type", "text/event-stream")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)
        self.wfile.flush()

    def log_message(self, *args):
        pass


def run():
    global http_success, ws_connect_fail
    parser = argparse.ArgumentParser()
    parser.add_argument("--http-only", action="store_true")
    parser.add_argument("--http-fail", action="store_true")
    parser.add_argument("--ws-connect-fail", action="store_true")
    parser.add_argument("--codex-bin", default="codex")
    args = parser.parse_args()
    http_success = not args.http_fail
    ws_connect_fail = args.ws_connect_fail
    server = ThreadingHTTPServer(("127.0.0.1", 0), MockResponses)
    threading.Thread(target=server.serve_forever, daemon=True).start()
    port = server.server_address[1]
    env = os.environ.copy()
    test_home = tempfile.mkdtemp(prefix="codex-transport-test-")
    env["CODEX_HOME"] = test_home
    env["CODEX_LOCAL_FAKE_KEY"] = "local-test-only"
    config = [
        'model_provider="local_fault"',
        'model_providers.local_fault.name="Local Fault"',
        f'model_providers.local_fault.base_url="http://127.0.0.1:{port}/v1"',
        'model_providers.local_fault.env_key="CODEX_LOCAL_FAKE_KEY"',
        'model_providers.local_fault.wire_api="responses"',
        f'model_providers.local_fault.supports_websockets={str(not args.http_only).lower()}',
        'model_providers.local_fault.stream_max_retries=0',
        'model_providers.local_fault.request_max_retries=0',
    ]
    command = [args.codex_bin, "app-server", "--stdio"]
    for item in config:
        command += ["-c", item]
    process = subprocess.Popen(
        command,
        stdin=subprocess.PIPE,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        bufsize=1,
        env=env,
    )
    output_lines: queue.Queue[str | None] = queue.Queue()

    def read_output():
        for line in process.stdout:
            output_lines.put(line)
        output_lines.put(None)

    threading.Thread(target=read_output, daemon=True).start()

    def send(obj):
        process.stdin.write(json.dumps(obj, ensure_ascii=False) + "\n")
        process.stdin.flush()

    def read_until(wanted_id=None, wanted_method=None, timeout=15):
        deadline = time.monotonic() + timeout
        observed = []
        while time.monotonic() < deadline:
            try:
                line = output_lines.get(timeout=max(0, deadline - time.monotonic()))
            except queue.Empty:
                break
            if line is None:
                break
            try:
                obj = json.loads(line)
            except json.JSONDecodeError:
                continue
            observed.append(obj)
            if wanted_id is not None and obj.get("id") == wanted_id:
                return obj, observed
            if wanted_method is not None and obj.get("method") == wanted_method:
                return obj, observed
        return None, observed

    try:
        send({"method": "initialize", "id": 1, "params": {"clientInfo": {"name": "codex_connection_diagnostic", "title": "Local fallback test", "version": "0.1.0"}, "capabilities": {"experimentalApi": True}}})
        result, _ = read_until(wanted_id=1)
        print("initialize", "ok" if result and "result" in result else result)
        send({"method": "initialized", "params": {}})
        send({"method": "thread/start", "id": 2, "params": {"model": "gpt-6-sol", "modelProvider": "local_fault", "ephemeral": True, "cwd": test_home, "sandbox": "read-only"}})
        result, _ = read_until(wanted_id=2)
        if not result or "error" in result:
            print("thread_start", result)
            return
        thread_id = result["result"]["thread"]["id"]
        print("thread_start", "ok", thread_id)
        time.sleep(0.3)
        before = len(events)
        send({"method": "thread/inject_items", "id": 3, "params": {"threadId": thread_id, "items": [{"type": "message", "role": "user", "content": [{"type": "input_text", "text": "Local compaction test history."}]}, {"type": "message", "role": "assistant", "content": [{"type": "output_text", "text": "Acknowledged."}]}]}})
        result, _ = read_until(wanted_id=3)
        print("inject", "ok" if result and "result" in result else result)
        send({"method": "thread/compact/start", "id": 4, "params": {"threadId": thread_id}})
        result, _ = read_until(wanted_id=4)
        print("compact_start", "ok" if result and "result" in result else result)
        completed, observed = read_until(wanted_method="turn/completed", timeout=20)
        print("compact_completed", bool(completed))
        if completed:
            turn = completed.get("params", {}).get("turn", {})
            print("turn_status", turn.get("status"), str(turn.get("error"))[:300])
        print("requests_after_compact", [(kind, path) for _, kind, path, _ in events[before:]])
        print("all_requests", [(kind, path) for _, kind, path, _ in events])
        print("event_methods", [o.get("method") for o in observed if o.get("method")][-15:])
    finally:
        process.stdin.close()
        try:
            process.wait(timeout=4)
        except subprocess.TimeoutExpired:
            process.terminate()
            process.wait(timeout=4)
        server.shutdown()
        errors = process.stderr.read()
        print("stderr_relevant", [line[-260:] for line in errors.splitlines() if "falling back" in line.lower() or "websocket" in line.lower() or "HTTP" in line][-10:])
        shutil.rmtree(test_home)


if __name__ == "__main__":
    run()
```
